package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strings"
	"unicode/utf8"
)

const profileSettingsKey = "profile"

// CustomPassion is the passion id used when the owner typed their own.
const CustomPassion = "custom"

// DefaultAccent is used when a persona has no valid accent colour.
const DefaultAccent = "#7C5CFF"

var accentPattern = regexp.MustCompile(`^#[0-9a-fA-F]{6}$`)

// Persona is the voice and look a passion gives the main agent. Built-in passions
// are JSON packs; a custom passion is generated by the model, so every field is
// untrusted until NormalizePersona has clamped it.
type Persona struct {
	ID                string   `json:"id"`
	Title             string   `json:"title"`
	Emoji             string   `json:"emoji"`
	SystemPromptStyle string   `json:"system_prompt_style"`
	GreetingTemplates []string `json:"greeting_templates"` // {name} = owner, {agent} = main agent
	DailyFeedQueries  []string `json:"daily_feed_queries"`
	AccentColor       string   `json:"accent_color"`
	AvatarSet         []string `json:"avatar_set"`
}

// Persona limits. They bound what a model (or an imported pack) can put in the
// main agent's prompt and in the UI.
const (
	maxStyle     = 800
	maxGreetings = 6
	maxGreeting  = 140
	maxQueries   = 5
	maxQuery     = 120
	maxAvatars   = 8
	maxAvatar    = 16
	maxTitle     = 60
)

// NormalizePersona trims and clamps a persona and fills what is missing. It
// returns an error only when nothing usable is left (no style).
func NormalizePersona(p *Persona) error {
	p.ID = strings.TrimSpace(p.ID)
	p.Title = clip(strings.TrimSpace(p.Title), maxTitle)
	p.Emoji = clip(strings.TrimSpace(p.Emoji), maxAvatar)
	p.SystemPromptStyle = clip(strings.TrimSpace(p.SystemPromptStyle), maxStyle)
	p.GreetingTemplates = cleanList(p.GreetingTemplates, maxGreetings, maxGreeting)
	p.DailyFeedQueries = cleanList(p.DailyFeedQueries, maxQueries, maxQuery)
	p.AvatarSet = cleanList(p.AvatarSet, maxAvatars, maxAvatar)
	if !accentPattern.MatchString(p.AccentColor) {
		p.AccentColor = DefaultAccent
	}
	if p.SystemPromptStyle == "" {
		return errors.New("a persona needs a system_prompt_style")
	}
	if len(p.GreetingTemplates) == 0 {
		p.GreetingTemplates = []string{"Hello, {name}. {agent} here. What should we work on?"}
	}
	if p.Emoji == "" && len(p.AvatarSet) > 0 {
		p.Emoji = p.AvatarSet[0]
	}
	return nil
}

func clip(s string, max int) string {
	if utf8.RuneCountInString(s) <= max {
		return s
	}
	return string([]rune(s)[:max])
}

func cleanList(in []string, maxItems, maxLen int) []string {
	out := []string{}
	seen := map[string]bool{}
	for _, v := range in {
		v = clip(strings.TrimSpace(v), maxLen)
		if v == "" || seen[v] {
			continue
		}
		seen[v] = true
		out = append(out, v)
		if len(out) == maxItems {
			break
		}
	}
	return out
}

// Profile records who the owner is and how they set up their staff. A zero
// Profile (Onboarded false) means onboarding has not been completed.
type Profile struct {
	Onboarded  bool    `json:"onboarded"`
	AgentName  string  `json:"agent_name"`
	Profession string  `json:"profession"` // profession pack id
	Passion    Persona `json:"passion"`    // the resolved persona, copied from the pack or generated
	// CustomPassion is what the owner typed when the passion is "custom".
	CustomPassion string   `json:"custom_passion,omitempty"`
	Stack         []string `json:"stack"`
}

func (s *Store) GetProfile(ctx context.Context) (Profile, error) {
	var out Profile
	var raw string
	err := s.db.QueryRowContext(ctx, `SELECT value FROM settings WHERE key = ?`, profileSettingsKey).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return out, nil
	}
	if err != nil {
		return out, err
	}
	if err := json.Unmarshal([]byte(raw), &out); err != nil {
		return Profile{}, fmt.Errorf("stored profile is unreadable: %w", err)
	}
	return out, nil
}

func (s *Store) PutProfile(ctx context.Context, p Profile) error {
	raw, err := json.Marshal(p)
	if err != nil {
		return err
	}
	_, err = s.db.ExecContext(ctx, `INSERT INTO settings (key, value) VALUES (?, ?)
		ON CONFLICT(key) DO UPDATE SET value = excluded.value`, profileSettingsKey, string(raw))
	return err
}
